197	impl Soc {
198	    /// After an erase or page program: the XIP window shows the flash chip, also where the
199	    /// window's contents come from the package (`xip`, the app area as installed). A booted
200	    /// package's window reaches flash 0x93000, and April OS writes its samples from 0x74000
201	    /// and reads them back through XIP.
202	    fn sync_xip(&mut self) {
203	        let Some((a, b)) = self.flash.changed.take() else { return };
204	        if !self.xip_flash {
205	            return;
206	        }
207	        for o in a.max(XIP_FLASH_OFFSET)..b {
208	            match self.xip.get_mut(o - XIP_FLASH_OFFSET) {
209	                Some(x) => *x = self.flash.mem[o],
210	                None => break,
211	            }
212	        }
213	    }
214	
215	    /// A saved flash chip in place of the booted one (fm1-live --flash): each 4 KiB sector that
216	    /// differs goes to the chip and, as the firmware's own erases and programs do, through to
217	    /// the XIP window (whose installed copy would otherwise still show the package's bytes).
218	    pub fn restore_flash(&mut self, image: &[u8]) {
219	        let n = image.len().min(spiflash::FLASH_SIZE);
220	        for at in (0..n).step_by(4096) {
221	            let end = (at + 4096).min(n);
222	            if self.flash.mem[at..end] != image[at..end] {
223	                self.flash.mem[at..end].copy_from_slice(&image[at..end]);
224	                self.flash.changed = Some((at, end));
225	                self.sync_xip();
226	                self.flash.revision = self.flash.revision.wrapping_add(1);
227	            }
228	        }
229	    }
