353	    fn region(&self, addr: u32) -> Region {
354	        match addr {
355	            a if a >= XIP_BASE && (a - XIP_BASE) < self.xip.len() as u32 => Region::Xip,
356	            // past the loaded image the XIP window still shows the flash chip (the stock
357	            // firmware reads its USR preset area, which it writes over SPI, through XIP)
358	            a if self.xip_flash && a >= XIP_BASE && (a - XIP_BASE) as usize + XIP_FLASH_OFFSET < spiflash::FLASH_SIZE => Region::XipFlash,
359	            a if a >= RAM_BASE && (a - RAM_BASE) < self.ram.len() as u32 => Region::Ram,
360	            a if a >= OVL_BASE && (a - OVL_BASE) < self.ovl.len() as u32 => Region::Ovl,
361	            a if a >= SRAM2_BASE && (a - SRAM2_BASE) < self.sram2.len() as u32 => Region::Sram2,
362	            0x1eee000..=0x1eee0ff => Region::Irqc,
363	            0x1eef000..=0x1eef3ff => Region::Irqc2,
364	            0x12e00..=0x12e3f => Region::Alnk,
365	            0x50000..=0x501ff => Region::Gpio,
366	            0x51000..=0x5103f => Region::Iomap,
367	            0x10000..=0x1001f => Region::Clk,
368	            0x10400..=0x1091f => Region::Timer,
369	            0x11c00..=0x11c1f => Region::Spi0,
370	            0x11d00..=0x11d1f => Region::Spi1,
371	            0x11e00..=0x11e1f => Region::Spi2,
372	            0x11800..=0x1183f => Region::Usb,
373	            // the second USB PHY (the SMK-37's LED commons at 0x16A0C, its pads used as GPIO; its
374	            // stock firmware powers the PHY up at boot and waits for 0x16800 bit 4). The FM-1's
375	            // stock firmware touches the block too, as before: unknown.
376	            0x16800..=0x16a1f if self.board == Board::Smk37 => Region::Usb,
377	            0x12100..=0x1212f => Region::Uart1,
378	            0x13100..=0x1311f => Region::Adc,
379	            0x13500..=0x1350f => Region::Crc,
380	            0x13b00..=0x13b07 => Region::Rand,
381	            0x11900..=0x119ff => Region::Ana,
382	            0x13e08..=0x13e0f => Region::P33,
383	            0x20000..=0x2ffff => Region::Bt,
384	            0x1eee240..=0x1eee24f => Region::Dbg,
385	            _ => Region::Unknown,
386	        }
387	    }
