397	    /// SPI1/MMIO side effects on 32-bit writes.
398	    fn spi1_write(&mut self, addr: u32, value: u32) {
399	        match addr {
400	            0x11d00 => {
401	                // CON: bit14 clears the pending transfer-done (and its IRQ 16)
402	                if value & 0x4000 != 0 {
403	                    self.periph.spi1_pending = false;
404	                }
405	                let stored = self.sfr_get(addr);
406	                self.sfr_set(addr, (stored & !0x4000) | (value & !0x4000));
407	            }
408	            0x11d04 => self.sfr_set(addr, value), // BAUD
409	            0x11d08 => {
410	                // BUF: single byte, D/C = PC8 state (SMK-37: PB5; its group B is the pad LEDs)
411	                if let Some(dc) = self.lcd_dc() {
412	                    self.lcd.feed(value as u8, dc);
413	                }
414	                self.sfr_set(addr, value);
415	                self.spi1_done(1);
416	            }
417	            0x11d0c => self.sfr_set(addr, value), // ADR
418	            0x11d10 => {
419	                // CNT: DMA `value` bytes from RAM[ADR] through the panel
420	                let adr = self.sfr_get(0x11d0c);
421	                let n = value.min(0x40000);
422	                // the DMA source is a bus address (RAM, SRAM or XIP)
423	                let bytes: Vec<u8> = (0..n).map(|i| self.read8(adr.wrapping_add(i))).collect();
424	                match self.lcd_dc() {
425	                    Some(dc) => {
426	                        for b in bytes {
427	                            self.lcd.feed(b, dc);
428	                        }
429	                    }
430	                    None => self.periph.smk.pad_frame(&bytes),
431	                }
432	                self.sfr_set(addr, 0);
433	                self.spi1_done(n);
434	            }
435	            _ => self.sfr_set(addr, value),
436	        }
437	    }
438	
439	    /// Where SPI1's bytes go: the LCD with its D/C pin's state (FM-1: PC8; SMK-37: PB5, while
440	    /// IOMAP_CON1 bit 4 picks pin group A), or None: the SMK-37's pad LEDs (group B).
441	    fn lcd_dc(&mut self) -> Option<bool> {
442	        match self.board {
443	            Board::Fm1 => Some(self.sfr_get(0x50080) & 0x100 != 0),
444	            Board::Smk37 => (self.sfr_get(0x51020) & 0x10 == 0).then(|| self.sfr_get(0x50040) & 0x20 != 0),
445	        }
446	    }
447	
448	    /// SPI2 (0x11E00, CON/BAUD/BUF/ADR/CNT like SPI1): the stock firmware shifts the key
449	    /// matrix's column pattern into the two 74HC595s with it, one 2-byte DMA per column,
450	    /// driven by its IRQ 37 handler (which also reads the rows and pulses RCLK on PA1).
451	    fn spi2_write(&mut self, addr: u32, value: u32) {
452	        match addr {
453	            0x11e00 => {
454	                if value & 0x4000 != 0 {
455	                    self.periph.spi2_pending = false;
456	                }
457	                self.sfr_set(addr, value & !0xc000);
458	            }
459	            0x11e08 => {
460	                self.periph.sr_shift_byte(value as u8);
461	                self.sfr_set(addr, value);
462	                self.spi2_started(1);
463	            }
464	            0x11e10 => {
465	                let adr = self.sfr_get(0x11e0c);
466	                for i in 0..value.min(64) {
467	                    let b = self.read8(adr.wrapping_add(i));
468	                    self.periph.sr_shift_byte(b);
469	                }
470	                self.sfr_set(addr, 0);
471	                self.spi2_started(value);
472	            }
473	            _ => self.sfr_set(addr, value),
474	        }
475	    }
476	
477	    fn spi2_started(&mut self, bytes: u32) {
478	        let con = self.sfr_get(0x11e00);
479	        let baud = self.sfr_get(0x11e04);
480	        self.periph.spi2_start(bytes, baud, con & 0x2000 != 0);
481	    }
482	
483	    /// A SPI1 transfer finished (instantly here): with CON bit 13 (interrupt enable) that is
484	    /// IRQ 16, the stock LCD driver's DMA-done (its layer flush waits for the handler).
485	    /// (SMK-37: it takes the bytes' time on the wire, see `Periph::spi1_start`.)
486	    fn spi1_done(&mut self, bytes: u32) {
487	        let irq = self.sfr_get(0x11d00) & 0x2000 != 0;
488	        if self.board == Board::Smk37 {
489	            let baud = self.sfr_get(0x11d04);
490	            self.periph.spi1_start(bytes, baud, irq);
491	        } else if irq {
492	            self.periph.spi1_pending = true;
493	        }
494	    }
495	
496	    fn timer_read(&mut self, addr: u32) -> u32 {
497	        // "time" base ticks so timeout/wait loops make progress; count
498	        // registers report a moving value, the rest stored bits.
499	        self.ticks = self.ticks.wrapping_add(1);
500	        if addr & 0xff == 0x04 {
501	            let t = (self.ticks * 7) as u32;
502	            return t;
503	        }
504	        self.sfr_get(addr)
505	    }
506	}
