586	    #[inline(always)]
587	    fn read16(&mut self, addr: u32) -> u16 {
588	        // halfwords sit at offsets 0 and 2 of the word (the old `>> 8` for
589	        // offset 2 returned bytes 1-2 and sheared every 16-bit pixel canvas)
590	        let v = self.read32(addr & !3);
591	        (v >> ((addr & 2) * 8)) as u16
592	    }
