594	    #[inline(always)]
595	    fn read32(&mut self, addr: u32) -> u32 {
596	        let o = addr.wrapping_sub(RAM_BASE) as usize;
597	        if o + 4 <= self.ram.len() {
598	            return self.ram.read32(o as u32);
599	        }
600	        let x = addr.wrapping_sub(XIP_BASE) as usize;
601	        if x + 4 <= self.xip.len() {
602	            return u32::from_le_bytes([self.xip[x], self.xip[x + 1], self.xip[x + 2], self.xip[x + 3]]);
603	        }
604	        self.read32_slow(addr)
605	    }
