607	    #[inline(always)]
608	    fn write8(&mut self, addr: u32, value: u8) {
609	        let o = addr.wrapping_sub(RAM_BASE);
610	        if (o as usize) < self.ram.len() {
611	            return self.ram.write8(o, value);
612	        }
613	        self.write8_slow(addr, value)
614	    }
