            let mut by: Vec<_> = irq_by.iter().collect();
            by.sort_by(|a, b| b.1.cmp(a.1));
            let by: Vec<String> = by.iter().take(8).map(|((c, n), k)| format!("c{c} irq {n} x{k}")).collect();
