    pub revision: u32,
    pub inverted: bool,
    /// pixels received since the last RAMWR (trace aid)
    pub pixels_in_window: u64,
    pub display_on: bool,
}

impl Default for Lcd {
    fn default() -> Self {
        Self::new()
    }
}

